userscript.function:

var alias = Sepoa.request.alias;

btn_flag = btn;
btnObj.showButton('confirm', false);
btnObj.showButton('reject', false);

//메일링크로 접속했을경우. SCREEN_TYPE이 존재함
if(paramObj.SCREEN_TYPE != undefined){
	screenType = paramObj.SCREEN_TYPE.substring(0,2);
	btnObj.showButton('back', false);
}

dataOutput.setValue('COMPANY_CODE', paramObj.COMPANY_CODE);
dataOutput.setValue('APP_NO', paramObj.APP_NO);
dataOutput.setValue('APP_NO_SEQ', paramObj.APP_NO_SEQ);
dataOutput.setValue('RE_FLAG', paramObj.RE_FLAG);
gridObj.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doQuery', 'METHOD=getAppLine', 'PROCESS_ID=sepoa.svc.approval.SepoaApprovalService']);
gridObj.clearAll(false);


            if (count == 0) {
                Alert(Sepoa.cache.text.get('MESSAGE.1001'));
                return;
            } else {
                for (var i = 0; i < count; i++) {
                    var rId = gridObj.getRowId(i);
                    if (gridObj.gridGetCellValueId(rId, 'APP_LINE_STATUS') == 'L04') { //결재자인지
                        if (gridObj.gridGetCellValueId(rId, 'APP_USER_ID') == Sepoa.info.ID) { //해당 결재자가 로그인한 사용자인지
                            btnObj.showButton('confirm', true);
                            btnObj.showButton('reject', true);
                        } else {
                            var app_user_id = gridObj.gridGetCellValueId(rId, 'APP_USER_ID');
                            doServiceAjax('sepoa.svc.approval.SepoaApprovalService', 'CONNECTION', 'doCheckDelegation', {
                                APP_USER_ID: app_user_id
                            }, function(so) {
                                if (so.status == '1') { //로그인한 사용자가 수임자일 경우
                                    var sf = new SepoaFormater(so.result[0]);
                                    if (sf.dataMap.GIVE_USER_ID.indexOf(gridObj.gridGetCellValueId(rId, 'APP_USER_ID')) > -1) {
                                        btnObj.showButton('confirm', true);
                                        btnObj.showButton('reject', true);
                                    } else {
                                        Alert(Sepoa.cache.text.get('MESSAGE.1008'));
                                        return false;
                                    }
                                } //참조자일 경우
                            });
                        }
                        break;
                    }
                }

                gridObj.forEachRowA(function(id) {
					if(gridObj.cells(id, gridObj.getColIndexById('APP_LINE_STATUS')).getValue() == "" && gridObj.cells(id, gridObj.getColIndexById('APP_METHOD')).getValue() != '04'){
						gridObj.cells(id, gridObj.getColIndexById('APP_LINE_STATUS')).setValue("L06");
						gridObj.cells(id, gridObj.getColIndexById('APP_LINE_SEQ_VIEW')).setValue("-");
					} else if (gridObj.cells(id, gridObj.getColIndexById('APP_LINE_STATUS')).getValue() == "" && gridObj.cells(id, gridObj.getColIndexById('APP_METHOD')).getValue() == '04' ){
						gridObj.cells(id, gridObj.getColIndexById('APP_LINE_STATUS')).setValue("L04");
					}
				})  
            }

            if (btn_flag == 'N') {
                btn_false();
            }


        		btnObj.showButton('confirm', false);
	            btnObj.showButton('reject', false);
	            btnObj.showButton('back', false);

	            if(clear =='Y'){
	            	gridObj.clearAll();
	            }


var header = gridObj.getColumnId(cInd);
if (header == 'ACCEPT_REASON') {
    var contents = gridObj.cells(rId, gridObj.getColIndexById("ACCEPT_REASON")).getValue();
    if (contents.trim() != '') {
        var param = {
            title: Sepoa.cache.text.get('AP_111.ACCEPT_REASON'),
            mode: 'VIEW',
            APP_COMMENT: contents
        }
        popupReason(param);
    }
}


let appComment = data.mode=='WRTIE' ? Sepoa.cache.text.get('APP_COMMENT.APP_COMMENT_DEFAULT') : '';
    sUtils.popup.modal({
        url: '/UxDefault/Common/WindowForm.sux',
        title: data.title,
        header: true,
        params: {
            mode: data.mode,
            form: 'APP_COMMENT',
            data: sUtils.object.extend(true, {APP_COMMENT : appComment}, data), 
            callback: data.callback || function() {}
        }
    })


if (type == 'CONFIRM') {
    var title = Sepoa.cache.text.get('AP_111.CONFIRM_REASON');
    var callbackFn = doConfirm;
    var Mod = 'WRTIE';
} else if (type == 'REJECT') {
    var title = Sepoa.cache.text.get('AP_111.REJECT_REASON');
    var callbackFn = doReject;
    var Mod = 'REJECT';
} else {
    return false;
}
var param = {
    mode: Mod,
    title: title,
    callback: callbackFn
}
popupReason(param);


dataOutput.setValue('ACCEPT_REASON', obj.APP_COMMENT);
if (imgUpdateFlag) {
    callFunction('SLM_123', 'doSave', [null, 'APP']);
}
setConfirmMessageOnProgress();
const so = doServiceAjax('sepoa.svc.approval.SepoaApprovalService', 'TRANSACTION', 'doApprovalConfirm', null, null, false);
if (so?.status == '1') {
    Alert(Sepoa.cache.text.get('MESSAGE.0001'), function() {
        if(screenType == 'MS'){
            btnObj.showButton('confirm', false);
            btnObj.showButton('reject', false);
            btnObj.showButton('back', false);
        } else {
            doBack();
        }
    });
    return true;
} else {
    Alert(so.message);
    return false;
}


        	// 승인시 컨버팅이 오래걸려서 프로그레스 이미지 아래에 메시지 세팅. 백프로세스로 만들기 전 임시처리니까 백프로세스 만들면 삭제 필요
        	setTimeout(function(){
        		if ($(parent.document.querySelector('.dhxtabbar_base_material div.dhx_cell_tabbar div.dhx_cell_progress_img')).length > 0) {
					$(parent.document.querySelector('.dhxtabbar_base_material div.dhx_cell_tabbar div.dhx_cell_progress_img')).append('<div style="width: 100%;height: 100%;display: flex;justify-content: center;align-items: center;text-align:center;padding-top:50px;font-size: 1.2rem;font-weight: 500;color:#7a7a7a;">진행중이니 기다려주세요.</div>');
				}
        	}, 1000);


dataOutput.setValue('ACCEPT_REASON', obj.APP_COMMENT);
const so = doServiceAjax('sepoa.svc.approval.SepoaApprovalService', 'TRANSACTION', 'doApprovalReject', null, null, false);

if (so.status == '1') {
    Alert(Sepoa.cache.text.get('MESSAGE.0001'), function() {
        if(screenType == 'MS'){
            btnObj.showButton('confirm', false);
            btnObj.showButton('reject', false);
            btnObj.showButton('back', false);
        } else {
            doBack();
        }
    });
    return true;
} else {
    Alert(so.message);
    return false;
}
